const getHeaders = (
  ...sources: (RequestInit['headers'] | Record<string, string | undefined>)[]
) => {
  const seen = new Set<string>();
  const layers: [string, string | readonly string[]][][] = [];
  for (const source of sources.reverse()) {
    if (!source) continue;
    const entries =
      source instanceof Headers
        ? source.entries()
        : Symbol.iterator in source
          ? Array.from(
              source as Iterable<Iterable<string>>,
              (entry) => Array.from(entry) as [string, string],
            )
          : Object.entries<string | readonly string[] | undefined>(source);
    const layer: [string, string | readonly string[]][] = [];
    for (const [name, value] of entries) {
      if (value !== undefined && !seen.has(name.toLowerCase())) layer.push([name, value]);
    }
    for (const [name] of layer) seen.add(name.toLowerCase());
    layers.push(layer);
  }
  return Object.fromEntries(layers.reverse().flat()) as Extract<
    RequestInit['headers'],
    Record<string, unknown>
  >;
};

export const getTaskServiceInternalRoutes = (fetchFn: typeof globalThis.fetch = fetch) => {
  const getApplyAutomationTaskActionInternalUrl = (taskKey: string) => {
    return `/internal/v1/tasks/${taskKey}/automation-actions`;
  };

  /**
   * Requires the signed `automation-service` issuer, `automation` actor with the rule ID,
   * `task-service` audience and organization. Automation validates the `task.created.v1` or
   * `task.status-changed.v1` event and binds the task key and organization to that event. It
   * selects the action of its current enabled rule in that organization, using the authority
   * recorded at rule creation. It ignores `task.status-changed.v1` events from `automation`
   * actors.
   *
   * Before applying or replaying an action, Task reads the current membership of its rule
   * author and any assignee from Organization. In the tenant transaction, Task locks the target,
   * verifies that the task and its parents are active, and checks that the matching local
   * membership still gives the author effective edit permission on the task. The rule ID remains
   * the actor for all activity and events. Assignment also
   * applies Task's current recipient eligibility and assignee limit. An unchanged priority or
   * an existing eligible assignee yields `no_op`. A change commits the command receipt, write,
   * activity and usual task outbox entries together.
   *
   * This command accepts only `assign` and `priority`. Automatic comments have their own
   * Task command. Notification handles the `notify` action and checks current task access
   * through the automation notification authorization operation.
   * @summary Apply an enabled rule's task action to the task in its triggering event
   */
  const applyAutomationTaskActionInternal = async (
    taskKey: string,
    automationTaskActionCommand: AutomationTaskActionCommand,
    options?: RequestInit,
  ): Promise<applyAutomationTaskActionInternalResponse> => {
    const res = await fetchFn(getApplyAutomationTaskActionInternalUrl(taskKey), {
      ...options,
      method: 'POST',
      headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
      body: JSON.stringify(automationTaskActionCommand),
    });

    const body = [204, 205, 304].includes(res.status) ? null : await res.text();

    const data: applyAutomationTaskActionInternalResponse['data'] = body ? JSON.parse(body) : {};
    return {
      data,
      status: res.status,
      headers: res.headers,
    } as applyAutomationTaskActionInternalResponse;
  };

  const getApplyAutomationTaskCommentInternalUrl = (taskKey: string) => {
    return `/internal/v1/tasks/${taskKey}/automation-comments`;
  };

  /**
   * Requires signed issuer `automation-service`, audience `task-service`, an organization
   * and an `automation` actor whose ID is the rule UUIDv7 in canonical lowercase form.
   * Automation signs that form so every retry uses the same actor-scoped receipt. It binds
   * the command to the task key and organization of a validated `task.created.v1` or
   * `task.status-changed.v1` event, ignores automation-authored status events, and selects
   * the action and recorded author of its current enabled rule in that organization.
   *
   * Task uses the signed organization only. It reads the rule author's current membership
   * from Organization and checks the matching local membership and effective `edit` access
   * on the active task and its active parent scope before receipt lookup or replay. The
   * write transaction locks and rechecks those local conditions.
   * The signed rule is the author of the comment, its activity and its event. On ordinary
   * comment reads, it has `actor.type: automation`, `mentions: []` and
   * `replyToCommentId: null`. The rule author's account ID serves only as authorization
   * evidence and is not exposed as the comment author. A human task editor who also manages
   * the current space may delete the comment through the ordinary moderation path.
   *
   * The comment, task version, comment activity, text-free `comment.created.v1` event with
   * current eligible watchers, and command receipt commit together. A replay returns the
   * recorded disposition without repeating those changes or recreating a moderated comment.
   * All responses send `Cache-Control: private, no-store`.
   * @summary Apply an enabled rule's comment action to its triggering task
   */
  const applyAutomationTaskCommentInternal = async (
    taskKey: string,
    automationTaskCommentCommand: AutomationTaskCommentCommand,
    options?: RequestInit,
  ): Promise<applyAutomationTaskCommentInternalResponse> => {
    const res = await fetchFn(getApplyAutomationTaskCommentInternalUrl(taskKey), {
      ...options,
      method: 'POST',
      headers: getHeaders({ 'Content-Type': 'application/json' }, options?.headers),
      body: JSON.stringify(automationTaskCommentCommand),
    });

    const body = [204, 205, 304].includes(res.status) ? null : await res.text();

    const data: applyAutomationTaskCommentInternalResponse['data'] = body ? JSON.parse(body) : {};
    return {
      data,
      status: res.status,
      headers: res.headers,
    } as applyAutomationTaskCommentInternalResponse;
  };

  return {
    applyAutomationTaskActionInternal,
    getApplyAutomationTaskActionInternalUrl,
    applyAutomationTaskCommentInternal,
    getApplyAutomationTaskCommentInternalUrl,
  };
};

